keep3('command','blankrect');% if exist('command') keep3 command; else clear; end  % clear variablesclose(findobj('type','figure'));                    % close all figures%----------------------------------------% Define Constants & Intialize variables%----------------------------------------arena = 16.1;       % mm arena height (perpendicular to flow), typically 22 or 16.1 mmMinWormArea = 0.5;   % Min area for object to be a valid wormMaxWormArea = 1.7;   % Max area for single wormMinDistance = 15;   % Min Distance for connecting a new worm to an existing track (in pixels)SizeChangeThreshold = 100;    % Max size change between frames (in pixels)  MinTrackLength = 10;    % Min Length of valid track (in frames)    PlotFrameRate = 60;     % Display tracking results every 'PlotFrameRate' framesQ = 1;      % Quit MATLAB aftewardsFrameRate = 2;  % Framerate (Hz)%TimeStamp = 1;  % SaveAll = 1;Gradient = 0;% % AutoSelectDyeTrack = 1;SaveThresholdMovie = 1;% % TrackDye = 1; ****SEE IF YOU CAN IGNORE DYE***% % TrackDye = 0;TrackWorms = 1;PackMemory = 600;bs = 5;  % pixels for background and dye levelsDefaultFragmentLength = 1800; % framesmax_processors = 6;num_processors = str2double(getenv('NUMBER_OF_PROCESSORS'));comp_name = getenv('COMPUTERNAME');check_status_interval = 30; %secondsMakeLocalCopy = false;%---------------------------------------% Set screen infoWTFigH = findobj('Tag', 'WTFIG');if isempty(WTFigH)    WTFigH = figure(20);    set(WTFigH, 'NumberTitle', 'off', 'Tag', 'WTFIG', 'Name', 'ArenaWormTracker');else    figure(WTFigH);endscrsz = get(0,'ScreenSize');set(WTFigH,'Position',[1 scrsz(4)*0.2 scrsz(3)-30 scrsz(4)*0.8]);StatusFigH = findobj('Tag', 'Status');if isempty(StatusFigH)    StatusFigH = figure(21);     set(StatusFigH, 'NumberTitle', 'off', 'Tag', 'StatFig', 'Name', 'Tracking Status');else    figure(StatusFigH);end%---------------------------------------%  Check for incomplete tracking files%---------------------------------------FinishPreviousTrackingSession = 0;% TempFolder = fullfile(matlabroot,'work');% if exist(TempFolder)==0 mkdir(TempFolder); end  % make TempFolder if it doesn't existTempFolder = fullfile(tempdir,'ArenaWormTracker');if ~exist(TempFolder,'dir')    mkdir(TempFolder);endStatusFile = fullfile(TempFolder,'inprogress.mat');delete(fullfile(TempFolder,'_F*')); % temporary files to monitor progressif exist(StatusFile,'file')==2    load(StatusFile);    if exist('File','var') && ~all([File.CompletedFragments])        FileNum = length(File);        FinishPreviousTrackingSession = 1;        disp('*** Unfinished jobs found.  Continuing tracking...');        for m = 1:length(File); File(m).ClaimedFragments = File(m).CompletedFragments; end % reset claimed fragments    endend    if ~FinishPreviousTrackingSession        %--------------------------    % Set Loop Parameters    %-------------------------    FileNum = str2double(cell2mat(inputdlg('How many files do you want to track?')));    clear File    Name(FileNum).MovieFile = '';    for MovieNum = 1:FileNum        UserPrompt = ['Select AVI Files For Analysis ' num2str(MovieNum)];        [FileName, PathName] = uigetfile('*.avi', UserPrompt);        cd(PathName);        Name(MovieNum).MovieFile = [PathName,FileName];        Name(MovieNum).TrackFile = strrepl(Name(MovieNum).MovieFile,'avi','mat');    end%     for MovieNum = 1:FileNum%         [pathname,filename,ext] = fileparts(Name(MovieNum).MovieFile);%         cd(pathname);%         UserPrompt = ['Save Track Data ',num2str(MovieNum),': ',filename];%         [FileName,PathName] = uiputfile('*.mat', UserPrompt,[filename,'.mat']);%         Name(MovieNum).TrackFile = [PathName,FileName];%     end    %-------------------------------    % Get User Input for each movie    %-------------------------------%     File(FileNum).MovieFile = '';    for MovieNum = 1:FileNum        MovieName = Name(MovieNum).MovieFile;        [p,ShortMovieName] = fileparts(MovieName);        TrackSettingsName = fullfile(p,[ShortMovieName,'_TrackSettings.mat']);        CollectTrackingSettings = true;        if exist(TrackSettingsName,'file') == 2            ButtonName = questdlg('Use existing tracking settings?','','Yes', 'No', 'Yes');            if strcmp(ButtonName,'Yes')                try                    load(TrackSettingsName);                    File(MovieNum) = FileSettings;                                        % check filenames                    [pn1,fn1] = fileparts(Name(MovieNum).MovieFile); % chosen                    [pn2,fn2] = fileparts(File(MovieNum).MovieFile); % from settings file                    if strcmp(fn1,fn2) % if filenames match                        if ~strcmp(pn1,pn2) % if pathnames don't match                            File(MovieNum).MovieFile = Name(MovieNum).MovieFile;                            File(MovieNum).TrackFile = Name(MovieNum).TrackFile;                        end                        CollectTrackingSettings = false;                    else                        disp('Filenames don''t match... reselect manually.');                    end                                        if ~isfield(File,'ClaimedFragments') || isempty(File(MovieFile).ClaimedFragments)                        File(MovieNum).ClaimedFragments = File(MovieNum).CompletedFragments;                    end                catch                    disp('Error loading settings.  Select manually...');                end            end        end        MovieObj = VideoReader(MovieName);                if CollectTrackingSettings            % show first frame            Mov = read(MovieObj, 10);  % read 10th frame, not first, as sometimes the first frame is too bright            Mov = Mov(:,:,3);            MovSize = size(Mov);            figure(WTFigH); clf; imshow(imadjust(Mov,[],[],2));            set(gcf,'MenuBar','none');            set(gcf,'Toolbar','none');            set(gcf,'Position',[1 1 1200 1200]);            %--------get information----------            buttony = 10;            %uicontrol('Style','text','Position',[20 buttony 90 20],'String','Timer Location: ');            %h1 = uicontrol('Style', 'popup','Position',[110 buttony 90 20],'String','Upper Right|Lower Right|Upper Left|Lower Left|None');             FrameNum = MovieObj.NumberOfFrames;            FrameStart = 1;            NumFragments = max(round(FrameNum/DefaultFragmentLength),1);            if NumFragments == min(max_processors,num_processors)+1 NumFragments = NumFragments - 1; end                         uicontrol('Style','text','Position',[230 buttony 40 20],'String','Frames');            h2a = uicontrol('style','edit','Position',[270 buttony 50 20],'String',num2str(FrameStart));            h2 = uicontrol('style','edit','Position',[320 buttony 50 20],'String',num2str(FrameNum));            h2b = uicontrol('style','edit','Position',[380 buttony 20 20],'String',num2str(NumFragments));            %h3 = uicontrol('style','checkbox','Position',[420 buttony 60 20],'String','Gradient');% %             h3 = uicontrol('style','checkbox','Position',[420 buttony 60 20],'String','Track Dye','Value',TrackDye);            uicontrol('Style','text','Position',[500 buttony 60 20],'String','Arena(mm)');            h4 = uicontrol('style','edit','Position',[560 buttony 40 20],'String',num2str(arena));            uicontrol('Style','text','Position',[640 buttony 60 20],'String','FrameRate');            h5 = uicontrol('style','edit','Position',[700 buttony 30 20],'String',num2str(FrameRate));            uicontrol('Style','text','Position',[770 buttony 50 20],'String','min/max');            h6a = uicontrol('style','edit','Position',[820 buttony 30 20],'String',num2str(MinWormArea));            h6b = uicontrol('style','edit','Position',[850 buttony 30 20],'String',num2str(MaxWormArea));            %--------------------------            set(WTFigH,'Name',['Movie ',num2str(MovieNum),': ',ShortMovieName]);            txt = 'Click background (PDMS)'; title(txt);            label = text(MovSize(2)/2,MovSize(1)*0.4,txt,'FontSize',18,'HorizontalAlignment','center');            [X,Y] = ginput(1); File(MovieNum).BgBox = [X-bs Y-bs 2*bs 2*bs];             rectangle('Position',File(MovieNum).BgBox); text(X+10,Y,'bg');            txt = 'SELECT Tracking Area: Regions outside the box will be blanked.'; title(txt);            title(txt); set(label,'String',txt);            box = getrect(WTFigH); box = box+(box==0); h = rectangle('Position',box); set(h,'EdgeColor',[0,0,0]);            File(MovieNum).MaskBox = box+(box==0);                       ar = 0;            % get tracking regions            txt = 'SELECT ARENA(S): click inside to confirm, outside to redo, Enter to end.';            title(txt); set(label,'String',txt);            success = 0; while success == 0                box = getrect(WTFigH); box = box+(box==0); h = rectangle('Position',box); set(h,'EdgeColor',[1,0,0]);                [X,Y,button] = ginput(1);                 if length(button) == 0                    success = true;                elseif button == 1 & (X-box(1) >= 0 & X-box(1) <= box(3) & Y-box(2) >= 0 & Y-box(2) <= box(4))                    ar = ar+1; % arena #                    File(MovieNum).Arena(ar).TrackBox = box+(box==0);                    set(h,'EdgeColor',[0,0,1]);                     ht = text(box(1)+box(3)/2,box(2)+box(4)/2,num2str(ar)); set(ht,'FontSize',36,'Color',[0 0 1]);                end            end            File(MovieNum).NumArenas = ar;% %             TrackDye = get(h3,'Value');            % get dye information            for a = 1:ar% %                 if TrackDye% %                     if AutoSelectDyeTrack% %                         box = File(MovieNum).Arena(a).TrackBox;% %                         File(MovieNum).Arena(a).UpBox = [box(1)-15-bs box(2)+box(4)/2-2*bs 2*bs 4*bs]; % %                             rectangle('Position',File(MovieNum).Arena(a).UpBox); text(X+10,Y,[num2str(a),'up']);% %                         File(MovieNum).Arena(a).DnBox = [box(1)+box(3)+15-bs box(2)+box(4)/2-2*bs 2*bs 4*bs]; % %                             rectangle('Position',File(MovieNum).Arena(a).DnBox); text(X+10,Y,[num2str(a),'dn']);% %                     else% %                         txt = ['Pick upstream and downstream points for Arena: ',num2str(a)];% %                         title(txt); set(label,'String',txt);% %                         [X,Y] = ginput(1); File(MovieNum).Arena(a).UpBox = [X-bs Y-2*bs 2*bs 4*bs]; % %                             rectangle('Position',File(MovieNum).Arena(a).UpBox); text(X+10,Y,[num2str(a),'up']);% %                         [X,Y] = ginput(1); File(MovieNum).Arena(a).DnBox = [X-bs Y-2*bs 2*bs 4*bs]; % %                             rectangle('Position',File(MovieNum).Arena(a).DnBox); text(X+10,Y,[num2str(a),'dn']);% %                     end% %                 else                    File(MovieNum).Arena(a).UpBox = [1 1 1 1];                    File(MovieNum).Arena(a).DownBox = [1 1 1 1];% %                 end             end            % get scale info            txt = ['GET SCALING: pick points on top and bottom arena edges = ',get(h4,'String'),'mm'];            title(txt); set(label,'String',txt);            [X,Y] = ginput(2);             arenapix = abs(Y(2)-Y(1));                         % extra rectangular region for exclusion             if exist('blankrect')                txt = 'SELECT EXTRA EXCLUSION REGION';                title(txt); set(label,'String',txt);                box = getrect(WTFigH); box = box+(box==0);                 blankrect = round(max(box,1));            end            while input('All settings made? (y/n)','s') ~= 'y';            end                        File(MovieNum).MovieFile = Name(MovieNum).MovieFile;            File(MovieNum).TrackFile = Name(MovieNum).TrackFile;            %File(MovieNum).TimeStamp = get(h1,'Value');            File(MovieNum).TrackFrames = str2num(get(h2,'String'));            File(MovieNum).StartFrame = str2num(get(h2a,'String'));            %File(MovieNum).Gradient = get(h3,'Value');% %             File(MovieNum).DyeTracked = get(h3,'Value');            File(MovieNum).ArenaSize = str2num(get(h4,'String'));            File(MovieNum).PixelSize = arenapix / File(MovieNum).ArenaSize;            File(MovieNum).ImageSize = MovSize;            File(MovieNum).FrameRate = str2num(get(h5,'String'));            File(MovieNum).Fragments = str2num(get(h2b,'String'));            File(MovieNum).MinMax = [str2num(get(h6a,'String')), str2num(get(h6b,'String'))];            File(MovieNum).StartFragment = 1;            File(MovieNum).CompletedFragments = zeros(1,File(MovieNum).Fragments);            File(MovieNum).ClaimedFragments = zeros(1,File(MovieNum).Fragments);            File(MovieNum).Stitched = 0;            hi = File(MovieNum).TrackFrames;            lo = File(MovieNum).StartFrame;            NumFragments = File(MovieNum).Fragments;            perfrag = round((hi-lo)/NumFragments/60)*60;            frfr = [lo+(0:(NumFragments-1))*perfrag]';            frfr = [frfr, [frfr(2:NumFragments)-1; hi]];            File(MovieNum).FragmentFrames = frfr;            disp([datestr(now),' Image Data Collected for Movie ',num2str(MovieNum)]);            FileSettings = File(MovieNum);            save(TrackSettingsName,'FileSettings');        end    end    save(StatusFile,'File');    end%---------------% Start Tracker%---------------for MovieNum = find(~[File.Stitched]);        %Gradient = File(MovieNum).Gradient;    FrameNum = File(MovieNum).TrackFrames;    Start = File(MovieNum).StartFrame;    %TimeStamp = File(MovieNum).TimeStamp;    ImageSize = File(MovieNum).ImageSize;    FrameRate = File(MovieNum).FrameRate;    PixelSize = File(MovieNum).PixelSize;    FragmentFrames = File(MovieNum).FragmentFrames;    MinWormArea = File(MovieNum).MinMax(1);    MaxWormArea = File(MovieNum).MinMax(2);    NumArenas = File(MovieNum).NumArenas;% %     TrackDye = File(MovieNum).DyeTracked;    NumFragments = File(MovieNum).Fragments;        if NumArenas >= 2        xdiv = mean([sum(File(MovieNum).Arena(1).TrackBox([1 3])),File(MovieNum).Arena(2).TrackBox(1)]); % x separation between arenas    end    if NumArenas == 4        ydiv = mean([sum(File(MovieNum).Arena(1).TrackBox([2 4])),File(MovieNum).Arena(3).TrackBox(2)]); % y separation between arenas    end        if MakeLocalCopy        TrackName = LocalDirectory(File(MovieNum).TrackFile);        MovieName = LocalDirectory(File(MovieNum).MovieFile);                % copy movie file if not already in local directory        if ~strcmp(File(MovieNum).MovieFile,MovieName)            p = fileparts(MovieName); if exist(p) == 0 mkdir(p); end  % make local copy folder if needed            disp([datestr(now),': Copying moviefile to local directory']);            [s,mess,messid] = copyfile(File(MovieNum).MovieFile,MovieName);            disp([datestr(now),': Complete... ',mess]);        end            else        TrackName = File(MovieNum).TrackFile;        MovieName = File(MovieNum).MovieFile;    end        [pathname,filename,ext] = fileparts(TrackName);    partsfolder = '\trackfile parts\';    FragmentSaveNames = {};     for i = 1:File(MovieNum).Fragments;        FragmentSaveNames = [FragmentSaveNames; {[pathname,partsfolder,filename,'_part',num2str(i),ext]}];     end    if exist([pathname,partsfolder]) == 0 mkdir([pathname,partsfolder]); end;        [p,ShortMovieName] = fileparts(MovieName);    %     FileInfo = aviinfo(MovieName);%     FileInfo2 = aviinfo(MovieName,'Robust');    Tracks = [];    AllData = [];% %     DyeData = [];% %     DyeData.Time = []; %DyeData.Up = []; DyeData.Down = []; % %     DyeData.Background = [];    ExpData = [];        %Video Mask:  remove bright or dim pixels (deals with timer)    MovieObj = VideoReader(MovieName);    Mov = read(MovieObj, MovieObj.NumberOfFrames);      MovData = Mov(:,:,3);    MaskPix = 10; MaskBorder = 30;%     Mask = (MovData <= MaskPix | MovData >= 255-MaskPix);%     Mask = imdilate(Mask,strel('square',3));    Mask = ones(size(MovData));        % added 20110504%     Mask(MaskBorder:ImageSize(1), MaskBorder:ImageSize(2)-MaskBorder) = 0;%     Mask(MaskBorder:ImageSize(1)-MaskBorder, MaskBorder:ImageSize(2)-MaskBorder) = 0;%     for a=1:File(MovieNum).NumArenas%         arenatrackbox = File(MovieNum).Arena(a).TrackBox;%         Mask(round(arenatrackbox(2)+(0:arenatrackbox(4))),MaskBorder:ImageSize(2)-MaskBorder) = 0;%     end    if isfield(File,'MaskBox')  % may need error handling here        Mask(round(File(MovieNum).MaskBox(2)+(0:File(MovieNum).MaskBox(4))), ...             round(File(MovieNum).MaskBox(1)+(0:File(MovieNum).MaskBox(3)))) = 0;    end    if exist('blankrect')         Mask(blankrect(2)+(0:blankrect(4)), blankrect(1)+(0:blankrect(3))) = 1;    end        tic;    %----------------------    % ANALYZE FRAGMENTS    %----------------------        claimed = File(MovieNum).ClaimedFragments;    completed = File(MovieNum).CompletedFragments;        while ~all(claimed)  % if any unclaimed fragments left...        fragments_left = find(~claimed);        next_fragment = min(fragments_left);                processors_used  = sum(claimed & ~completed);        if processors_used < min(num_processors, max_processors)                        claimed(next_fragment) = 1;            File(MovieNum).ClaimedFragments = claimed;            save(StatusFile,'File');                        % SPAWN new FragmentTracker            Fragment = next_fragment;            disp([datestr(now), '  spawning for fragment ',int2str(Fragment),'/',int2str(NumFragments)]);            disp(['  Fragments completed: ',sprintf('%1d ',completed)]);            disp(['  Fragments analyzing: ',sprintf('%1d ',claimed & ~completed)]);            fprintf('\n\n');                                SpawnSetting.Save = 1;  % save master workspace; slaves will load            SpawnSetting.Exit = 0;  % don't exit from master tracker            SpawnSetting.MatlabFlags = '-noFigureWindows -automation';            SpawnSetting.Startup = ['Fragment=',int2str(Fragment),';FragmentTracker_20171116_DL;'];                        spawn;                    end                pause(check_status_interval);                 % parse fragment status files        StatusD = dir(fullfile(TempFolder,'_F*')); StatusLine = [StatusD.name];        StatusM = zeros(1,NumFragments);        a = strfind(StatusLine,'.'); b = [strfind(StatusLine,'_'),length(StatusLine)+1]; b = circshift(b,[0 -1]); aF = strfind(StatusLine,'F');        for c = 1:length(a); StatusM(str2num(StatusLine(aF(c)+1:a(c)-1))) = str2num(StatusLine(a(c)+1:b(c)-1)); end % get percent progress from each fragment tracker                % show status window        figure(StatusFigH);        bar(StatusM); set(gca,'YLim',[0 100]);         ylabel('Completed (%)'); xlabel('Fragment Number');         title({[datestr(now),'  ',mat2str(StatusM)],[sprintf('[%d/%d] ',MovieNum,length(File)),File(MovieNum).TrackFile]},'Interpreter','none');               % update current status        loadsuccess = 0;        while ~loadsuccess             try                load(StatusFile,'File');                loadsuccess = 1;            catch                disp('Error loading status file.  Retrying...');                pause(5);            end        end                                        claimed = File(MovieNum).ClaimedFragments;        completed = File(MovieNum).CompletedFragments;        end   % END for file fragments        disp('all fragments seeded. waiting for slaves to finish computation...')        % Check that all fragments are completed    while length(dir([pathname,partsfolder,filename,'*'])) < NumFragments        %disp([datestr(now),'found ',int2str(length(dir([pathname,partsfolder,filename,'*']))),'/',int2str(NumFragments),' completed fragments.' ])        %dir([pathname,partsfolder,filename,'*'])        pause(check_status_interval)                % parse fragment status files        StatusD = dir(fullfile(TempFolder,'_F*')); StatusLine = [StatusD.name];        StatusM = zeros(1,NumFragments);        a = strfind(StatusLine,'.'); b = [strfind(StatusLine,'_'),length(StatusLine)+1]; b = circshift(b,[0 -1]); aF = strfind(StatusLine,'F');        for c = 1:length(a); StatusM(str2num(StatusLine(aF(c)+1:a(c)-1))) = str2num(StatusLine(a(c)+1:b(c)-1)); end % get percent progress from each fragment tracker                % show status window        figure(WTFigH);        bar(StatusM); set(gca,'YLim',[0 100]);         ylabel('Completed (%)'); xlabel('Fragment Number');         title({[datestr(now),'  ',mat2str(StatusM)],[sprintf('[%d/%d] ',MovieNum,length(File)),File(MovieNum).TrackFile]},'Interpreter','none');    end    disp('found all files. start stitching.')    % Save Combined File    StitchTracks_DL(FragmentSaveNames,TrackName);        % update current status    loadsuccess = 0;    while ~loadsuccess         try            load(StatusFile,'File');            loadsuccess = 1;        catch            disp('Error loading status file.  Retrying...');            pause(5);        end    end                                    File(MovieNum).Stitched = 1;    save(StatusFile,'File');        % Copy files back to original location    disp([datestr(now),': Copying tracks file from local directory']);    [s,mess,messid] = copyfile(TrackName,File(MovieNum).TrackFile);    disp([datestr(now),': Complete... ',mess]);        disp([datestr(now),': Copying avi.mat file(s) from local directory']);    [s,mess,messid] = copyfile([MovieName,'*.mat'],fileparts(File(MovieNum).TrackFile));    disp([datestr(now),': Complete... ',mess]);end    % END for i = 1:FileNameSize(1)%if all([File.CompletedFragments])    % if Q%     quit% end